def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    shifts = 0

    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            shifts += 1
            if shifts > 1:
                return False
            if i > 0 and arr[i - 1] > arr[i + 1]:
                return False
    # Check the last and first element condition
    if arr[n - 1] > arr[0]:
        shifts += 1
        if shifts > 1:
            return False

    return True
