```python
def modp(n: int, p: int) -> int:
    if n == 0:
        return 1
    result = 1
    base = 2
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        n = n // 2
    return result
```

